//! Cross-check the hand-written core-only codec against an independent layout
//! generated by simple_endian's `Endianize` derive. Host-only (needs std).
use simple_endian::{write_specific, Endianize};
use tb_rdma_proto::*;

#[derive(Endianize, Clone, Copy)]
#[endian(le)]
#[repr(C, packed)]
#[wire_repr(C, packed)]
#[wire_derive(Clone, Copy)]
struct OracleHeader {
    version: u8,
    opcode: u8,
    flags: u16,
    dst: u16,
    src: u16,
    ttl: u8,
    vc: u8,
    qpn: u32,
    psn: u32,
    ack_psn: u32,
    credits: u16,
    reserved: u16,
}

#[derive(Endianize, Clone, Copy)]
#[endian(le)]
#[repr(C, packed)]
#[wire_repr(C, packed)]
#[wire_derive(Clone, Copy)]
struct OracleReth {
    rkey: u32,
    offset: u64,
    length: u32,
}

fn oracle_bytes<W: simple_endian::EndianWrite>(w: &W) -> Vec<u8> {
    let mut v = Vec::new();
    write_specific(&mut v, w).unwrap();
    v
}

#[test]
fn header_matches_oracle() {
    let mut s = 0x1234_5678_9ABC_DEF1u64;
    let mut next = || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s
    };
    for _ in 0..10_000 {
        let r = next();
        let h = Header {
            opcode: Opcode::from_u8(1 + (r % 12) as u8).unwrap(),
            flags: (r >> 8) as u16 & flags::ALL,
            dst: (r >> 16) as u16,
            src: (r >> 24) as u16,
            ttl: (r >> 32) as u8,
            vc: (r >> 40) as u8,
            qpn: next() as u32,
            psn: next() as u32,
            ack_psn: next() as u32,
            credits: next() as u16,
        };
        let mut mine = [0u8; HEADER_LEN];
        h.encode(&mut mine).unwrap();
        let oracle = oracle_bytes(&OracleHeaderWire::from(OracleHeader {
            version: FORMAT_VERSION,
            opcode: h.opcode as u8,
            flags: h.flags,
            dst: h.dst,
            src: h.src,
            ttl: h.ttl,
            vc: h.vc,
            qpn: h.qpn,
            psn: h.psn,
            ack_psn: h.ack_psn,
            credits: h.credits,
            reserved: 0,
        }));
        assert_eq!(&mine[..], &oracle[..]);
        assert_eq!(Header::decode(&oracle).unwrap(), h);
    }
}

#[test]
fn reth_matches_oracle() {
    let r = Reth {
        rkey: 0xDEAD_BEEF,
        offset: 0x0102_0304_0506_0708,
        length: 4054,
    };
    let mut mine = [0u8; RETH_LEN];
    r.encode(&mut mine).unwrap();
    let oracle = oracle_bytes(&OracleRethWire::from(OracleReth {
        rkey: r.rkey,
        offset: r.offset,
        length: r.length,
    }));
    assert_eq!(&mine[..], &oracle[..]);
    assert_eq!(Reth::decode(&oracle).unwrap(), r);
}
